package com.loopers.application.product
import org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.client.TestRestTemplate;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.jdbc.Sql
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) @Sql("classpath:week4/product-query-seed.sql") class ProductQueryE2ETest @Autowired constructor(private val service:ProductQueryService,private val db:JdbcTemplate,private val http:TestRestTemplate){@Test fun fixedSeedAndOrderedResultAreStable(){assertThat(db.queryForObject("select count(*) from products",Long::class.java)).isEqualTo(10000);assertThat(db.queryForObject("select sum(price) from products",Long::class.java)).isEqualTo(472685000);assertThat(db.queryForObject("select count(*) from products where brand_id=7",Long::class.java)).isEqualTo(100);assertThat(db.queryForObject("select sum(price) from products where brand_id=7",Long::class.java)).isEqualTo(4647200);val first=service.find(7,20);assertThat(first).hasSize(20).isEqualTo(service.find(7,20));assertThat(first.zipWithNext().all{(a,b)->a.price<b.price||a.price==b.price&&a.id<b.id}).isTrue();assertThat(http.getForEntity("/api/v1/products?brandId=7&sort=price_asc&limit=20",String::class.java).statusCode.is2xxSuccessful).isTrue();db.update("update products set price=0 where id=?",first.first().id);service.priceChanged(7);assertThat(service.find(7,20).first().price).isZero()}}
